def is_not_prime(n):
    """
    Return True if n is NOT a prime number, False if it is prime.
    """
    if n < 2:
        return True
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return True
    return False

def differ_At_One_Bit_Pos(a, b):
    xor_result = a ^ b
    return xor_result != 0 and (xor_result & (xor_result - 1)) == 0

def find_Rotations(s):
    """
    Find how many times a string can be rotated such that it still 
    remains the same string (i.e., find the minimum number of rotations
    needed to get back to the original string).
    """
    n = len(s)
    if n == 0:
        return 0
    for i in range(1, n + 1):
        if s[i:] + s[:i] == s:
            return i
    return n

def remove_Occ(s, ch):
    """
    Remove the first and last occurrence of a given character from the string.
    """
    s = list(s)
    first_index = None
    last_index = None

    for i, c in enumerate(s):
        if c == ch:
            if first_index is None:
                first_index = i
            last_index = i

    if first_index is None:
        return "".join(s)

    if first_index == last_index:
        del s[first_index]
    else:
        # Remove last occurrence first to keep indices valid
        del s[last_index]
        del s[first_index]

    return "".join(s)

def remove_dirty_chars(string, chars_to_remove):
    for char in chars_to_remove:
        string = string.replace(char, "")
    return string

def check(num):
    reverse_num = int(str(num)[::-1])
    return num == 2 * reverse_num - 1

def smallest_num(nums):
    """
    Find the smallest number in a list.

    Returns the smallest number in the list.
    If the list is empty, returns None.
    """
    if not nums:
        return None
    return min(nums)

def is_Monotonic(arr):
    return all(arr[i] <= arr[i+1] for i in range(len(arr)-1)) or \
           all(arr[i] >= arr[i+1] for i in range(len(arr)-1))
